package com.officebox.pdf;
import org.apache.pdfbox.io.RandomAccessReadBuffer;import org.apache.pdfbox.multipdf.PDFMergerUtility;import org.springframework.http.MediaType;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.util.*;
@RestController @RequestMapping("/api/pdf") @CrossOrigin(origins="*")
public class PdfController{
 @PostMapping(value="/merge",consumes=MediaType.MULTIPART_FORM_DATA_VALUE,produces=MediaType.APPLICATION_PDF_VALUE) public byte[] merge(@RequestParam("files")List<MultipartFile> files)throws IOException{if(files==null||files.size()<2)throw new IllegalArgumentException("至少需要两个 PDF 文件");PDFMergerUtility merger=new PDFMergerUtility();List<RandomAccessReadBuffer> sources=new ArrayList<>();try{for(MultipartFile file:files){String n=Objects.requireNonNullElse(file.getOriginalFilename(),"").toLowerCase();if(!n.endsWith(".pdf"))throw new IllegalArgumentException("仅支持 PDF 文件");RandomAccessReadBuffer r=new RandomAccessReadBuffer(file.getInputStream());sources.add(r);merger.addSource(r);}ByteArrayOutputStream out=new ByteArrayOutputStream();merger.setDestinationStream(out);merger.mergeDocuments(null);return out.toByteArray();}finally{for(RandomAccessReadBuffer r:sources)try{r.close();}catch(IOException ignored){}}}
}
